  Button reset=new Button{Text="Reset All",Dock=DockStyle.Fill,Margin=Padding.Empty};Button add=new Button{Text="+",Dock=DockStyle.Fill,Margin=Padding.Empty};remove.Text="−";remove.Dock=DockStyle.Fill;remove.Margin=Padding.Empty;tools.Controls.Add(reset,0,0);tools.Controls.Add(add,2,0);tools.Controls.Add(remove,3,0);
