 static Icon LoadIcon(){using(Stream s=System.Reflection.Assembly.GetExecutingAssembly().GetManifestResourceStream("SmoothFlow.AppIcon"))using(Icon icon=new Icon(s,new Size(32,32)))return (Icon)icon.Clone();}
 static void InitCheck(CheckBox c,string text){c.Text=text;c.AutoSize=true;c.Margin=new Padding(0,5,22,0);c.AccessibleName=text;}
 void AddNumber(TableLayoutPanel panel,int row,string text,NumericUpDown n,int min,int max,int decimals){Label label=new Label{Text=text,Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleRight,Margin=new Padding(0,0,15,0)};panel.Controls.Add(label,0,row);n.Minimum=min;n.Maximum=max;n.DecimalPlaces=decimals;n.Increment=decimals>0?.1M:1;n.Width=82;n.MinimumSize=new Size(75,0);n.Anchor=AnchorStyles.Left;n.TextAlign=HorizontalAlignment.Center;n.AccessibleName=text;n.Margin=new Padding(0,3,0,3);panel.Controls.Add(n,1,row);}
 ScrollOptions Current(){return profiles.SelectedIndex>0?settings.Profiles[profiles.SelectedIndex-1]:(ScrollOptions)settings;}
 void ReloadProfiles(int index){updating=true;profiles.Items.Clear();profiles.Items.Add("Default (All Applications)");foreach(AppProfile p in settings.Profiles)profiles.Items.Add(p.ProcessName+".exe");profiles.SelectedIndex=Math.Max(0,Math.Min(index,profiles.Items.Count-1));autoStart.Checked=settings.AutoStart;updating=false;LoadProfile();}
 void LoadProfile(){updating=true;ScrollOptions o=Current();step.Value=(decimal)o.Distance;duration.Value=o.Duration;accelerationDelta.Value=o.AccelerationDelta;accelerationMax.Value=(decimal)o.AccelerationMax;tail.Value=(decimal)o.TailRatio;defaultEnabled.Text=profiles.SelectedIndex==0?"Enable for all apps by default":"Enable for this application";defaultEnabled.AccessibleName=defaultEnabled.Text;defaultEnabled.Checked=profiles.SelectedIndex==0?settings.DefaultEnabled:o.Enabled;easing.Checked=o.Easing;shift.Checked=o.ShiftHorizontal;horizontal.Checked=o.Horizontal;reverse.Checked=o.Reverse;remove.Enabled=profiles.SelectedIndex>0;updating=false;}
 void Changed(){if(updating)return;ScrollOptions o=Current();o.Distance=(double)step.Value;o.Duration=(int)duration.Value;o.AccelerationDelta=(int)accelerationDelta.Value;o.AccelerationMax=(double)accelerationMax.Value;o.TailRatio=(double)tail.Value;o.Easing=easing.Checked;o.ShiftHorizontal=shift.Checked;o.Horizontal=horizontal.Checked;o.Reverse=reverse.Checked;if(profiles.SelectedIndex==0)settings.DefaultEnabled=defaultEnabled.Checked;else o.Enabled=defaultEnabled.Checked;service.Configure(settings);QueueSave();}
 void QueueSave(){saveTimer.Stop();saveTimer.Start();}void Save(){try{settings.Save();saveError="";}catch(Exception ex){saveError=ex.Message;}}
 void SetEnabled(bool value){if(value&&OtherEngine()){service.SetEnabled(false);settings.Enabled=false;saveError="原 SmoothScroll 仍在运行，请退出后再勾选 Enabled。";}else{service.SetEnabled(value);settings.Enabled=service.Enabled;saveError="";}Save();RefreshStatus();}
 static bool OtherEngine(){foreach(string name in new string[]{"SmoothScroll","smoothscroll-app"}){Process[] ps=Process.GetProcessesByName(name);bool found=ps.Length>0;foreach(Process p in ps)p.Dispose();if(found)return true;}return false;}
 void RefreshStatus(){updating=true;globalEnabled.Checked=service.Enabled;updating=false;status.Text=service.Fault.Length>0?service.Fault:service.Notice.Length>0?service.Notice:saveError.Length>0?saveError:(service.Enabled?"已启用":"已暂停")+"  ·  关闭窗口隐藏到托盘  ·  Ctrl+Alt+S";tray.Text=service.Enabled?"SmoothFlow · 已启用":"SmoothFlow · 已暂停";}
 void AddProfile(){using(Form dialog=new Form{Text="Add application",Font=Font,StartPosition=FormStartPosition.CenterParent,ClientSize=new Size(380,140),FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false}){Label hint=new Label{Text="进程名，例如 Weixin.exe",Location=new Point(16,12),Size=new Size(345,25)};TextBox name=new TextBox{Location=new Point(16,44),Width=345};Button ok=new Button{Text="Add",Location=new Point(265,87),Size=new Size(95,30),DialogResult=DialogResult.OK};dialog.Controls.AddRange(new Control[]{hint,name,ok});dialog.AcceptButton=ok;ScaleDialog(dialog);if(dialog.ShowDialog(this)!=DialogResult.OK)return;string key=Settings.Normalize(name.Text);if(key.Length==0||key.IndexOfAny(new char[]{'\\','/',':','*','?'})>=0){MessageBox.Show(this,"请输入进程名，不要输入文件路径。");return;}AppProfile existing=settings.Find(key);if(existing!=null){profiles.SelectedIndex=settings.Profiles.IndexOf(existing)+1;return;}ScrollOptions o=Current();settings.Profiles.Add(new AppProfile{ProcessName=key,Distance=o.Distance,Duration=o.Duration,AccelerationDelta=o.AccelerationDelta,AccelerationMax=o.AccelerationMax,TailRatio=o.TailRatio,Easing=o.Easing,ShiftHorizontal=o.ShiftHorizontal,Horizontal=o.Horizontal,Reverse=o.Reverse,Enabled=true});ReloadProfiles(settings.Profiles.Count);Changed();}}
 static void ScaleDialog(Form dialog){dialog.AutoScaleMode=AutoScaleMode.None;using(Graphics g=Graphics.FromHwnd(IntPtr.Zero)){float f=g.DpiX/96F;if(f==1)return;foreach(Control child in dialog.Controls)ScaleUi(child,f);dialog.ClientSize=new Size(Scale(380,f),Scale(140,f));}}
 protected override void WndProc(ref Message m){if(m.Msg==0x312&&m.WParam.ToInt32()==1){SetEnabled(!service.Enabled);return;}base.WndProc(ref m);}
 static int Scale(int v,float f){return (int)Math.Round(v*f);}static Padding Pad(Padding p,float f){return new Padding(Scale(p.Left,f),Scale(p.Top,f),Scale(p.Right,f),Scale(p.Bottom,f));}
 static void ScaleUi(Control c,float f){c.SuspendLayout();c.Margin=Pad(c.Margin,f);c.Padding=Pad(c.Padding,f);c.MinimumSize=new Size(Scale(c.MinimumSize.Width,f),Scale(c.MinimumSize.Height,f));TableLayoutPanel t=c as TableLayoutPanel;if(t!=null){foreach(RowStyle r in t.RowStyles)if(r.SizeType==SizeType.Absolute)r.Height*=f;foreach(ColumnStyle col in t.ColumnStyles)if(col.SizeType==SizeType.Absolute)col.Width*=f;}c.SetBounds(Scale(c.Left,f),Scale(c.Top,f),Scale(c.Width,f),Scale(c.Height,f));foreach(Control child in c.Controls)ScaleUi(child,f);c.ResumeLayout(false);}
}
